// ARQUIVO GERADO por scripts/gen-source.mjs — não edite; altere grafos-geral.c e rode `npm run gen:source`.
export const C_SOURCE = "#include <stdio.h>\n#include <stdlib.h>\n#include <stdbool.h>\n\nstruct No {\n    int vertice;\n    struct No *prox;\n};\n\nstruct Grafo {\n    int v;\n    int e;\n    int **incidencia;\n    int **adjacencia;\n    struct No **listaAdjacencia;\n    int *grau;\n};\n\nvoid criarGrafo (struct Grafo *g, int v, int e) {\n    g->v = v;\n    g->e = e;\n    g->incidencia = (int **)malloc(v * sizeof(int *));\n    g->adjacencia = (int **)malloc(v * sizeof(int *));\n    g->listaAdjacencia = (struct No **)malloc(v * sizeof(struct No *));\n    g->grau = (int *)malloc(v * sizeof(int));\n\n    for (int i = 0; i < v; i++) {\n        g->incidencia[i] = (int *)malloc(e * sizeof(int));\n        g->adjacencia[i] = (int *)calloc(v, sizeof(int));\n        g->listaAdjacencia[i] = NULL;\n    }\n}\n\nvoid liberarGrafo (struct Grafo *g) {\n    for (int i = 0; i < g->v; i++) {\n        free(g->incidencia[i]);\n        free(g->adjacencia[i]);\n\n        struct No *atual = g->listaAdjacencia[i];\n        while (atual != NULL) {\n            struct No *aux = atual;\n            atual = atual->prox;\n            free(aux);\n        }\n    }\n    free(g->incidencia);\n    free(g->adjacencia);\n    free(g->listaAdjacencia);\n    free(g->grau);\n}\n\nvoid imprimirMatriz (int linhas, int colunas, int **matriz, char rotulo) {\n    printf(\"    \");\n    for (int j = 0; j < colunas; j++) {\n        printf(\"%c%-3d\", rotulo, j);\n    }\n    printf(\"\\n\");\n\n    for (int i = 0; i < linhas; i++) {\n        printf(\"v%-3d\", i);\n        for (int j = 0; j < colunas; j++) {\n            printf(\"%-4d\", matriz[i][j]);\n        }\n        printf(\"\\n\");\n    }\n}\n\n// Entrada e Validação \n\nbool validarColunas (struct Grafo *g) {\n    for (int aresta = 0; aresta < g->e; aresta++) {\n        int cont = 0;\n        for (int vertice = 0; vertice < g->v; vertice++) {\n            cont += g->incidencia[vertice][aresta];\n        }\n        if(cont != 2) {\n            printf(\"Erro: a aresta e%d tem %d vértice(s), deveria ter 2\\n\", aresta, cont);\n            return false;\n        }\n    }\n    return true;\n}\n\nbool validarParalelas (struct Grafo *g) {\n    for (int a = 0; a < g->e; a++) {\n        for (int b = a + 1; b < g->e; b++) {\n            int i = 0;\n            while (i < g->v && g->incidencia[i][a] == g->incidencia[i][b]) {\n                i++;\n            }\n            if(i == g->v) {\n                printf(\"Erro: as arestas e%d e e%d são paralelas\\n\", a, b);\n                return false;\n            }\n        }\n    }\n    return true;\n}\n\nbool moduloEntrada (struct Grafo *g) {\n    int v, e;\n\n    printf(\"===== ENTRADA E VALIDAÇÃO =====\\n\");\n    printf(\"Digite o número de vértices: \");\n    if(scanf(\"%d\", &v) != 1 || v < 1 || v > 20) {\n        printf(\"Erro: o número de vértices deve estar entre 1 e 20\\n\");\n        return false;\n    }\n\n    printf(\"Digite o número de arestas: \");\n    if(scanf(\"%d\", &e) != 1 || e < 0 || e > v * (v - 1) / 2) {\n        printf(\"Erro: o número de arestas deve estar entre 0 e %d\\n\", v * (v - 1) / 2);\n        return false;\n    }\n\n    criarGrafo(g, v, e);\n\n    if(e > 0) {\n        printf(\"Digite a matriz de incidência (%dx%d), uma linha por vértice:\\n\", v, e);\n    }\n    for (int i = 0; i < v && e > 0; i++) {\n        printf(\"Vértice %d: \", i);\n        for (int j = 0; j < e; j++) {\n            if(scanf(\"%d\", &g->incidencia[i][j]) != 1 || (g->incidencia[i][j] != 0 && g->incidencia[i][j] != 1)) {\n                printf(\"\\nErro: a matriz só pode ter valores 0 ou 1\\n\");\n                return false;\n            }\n        }\n    }\n\n    if(!validarColunas(g) || !validarParalelas(g)) {\n        return false;\n    }\n\n    printf(\"\\nMatriz válida! Grafo com %d vértice(s) e %d aresta(s).\\n\", v, e);\n    return true;\n}\n\n// Transformações \n\nvoid incidenciaParaAdjacencia (struct Grafo *g) {\n    for (int aresta = 0; aresta < g->e; aresta++) {\n        int u = -1;\n        int w = -1;\n\n        for (int vertice = 0; vertice < g->v; vertice++) {\n            if(g->incidencia[vertice][aresta] == 1) {\n                if(u == -1) {\n                    u = vertice;\n                }\n                else {\n                    w = vertice;\n                }\n            }\n        }\n        g->adjacencia[u][w] = 1;\n        g->adjacencia[w][u] = 1;\n    }\n}\n\nvoid adjacenciaParaLista (struct Grafo *g) {\n    for (int u = 0; u < g->v; u++) {\n        for (int w = g->v - 1; w >= 0; w--) {\n            if(g->adjacencia[u][w] == 1) {\n                struct No *novo = (struct No *)malloc(sizeof(struct No));\n                novo->vertice = w;\n                novo->prox = g->listaAdjacencia[u];\n                g->listaAdjacencia[u] = novo;\n            }\n        }\n    }\n}\n\nvoid moduloTransformacoes (struct Grafo *g) {\n    printf(\"\\n===== TRANSFORMAÇÕES =====\\n\");\n\n    incidenciaParaAdjacencia(g);\n    printf(\"Matriz de adjacência:\\n\");\n    imprimirMatriz(g->v, g->v, g->adjacencia, 'v');\n\n    adjacenciaParaLista(g);\n    printf(\"\\nLista de adjacência:\\n\");\n    for (int u = 0; u < g->v; u++) {\n        printf(\"Vértice %d: \", u);\n        for (struct No *p = g->listaAdjacencia[u]; p != NULL; p = p->prox) {\n            printf(\"%d -> \", p->vertice);\n        }\n        printf(\"NULL\\n\");\n    }\n}\n\n// Classificação \n\nint dfs (struct Grafo *g, int u, bool visitado[], int ignorar) {\n    int cont = 1;\n    visitado[u] = true;\n    for (struct No *p = g->listaAdjacencia[u]; p != NULL; p = p->prox) {\n        if(p->vertice != ignorar && !visitado[p->vertice]) {\n            cont += dfs(g, p->vertice, visitado, ignorar);\n        }\n    }\n    return cont;\n}\n\nint contarAlcancados (struct Grafo *g, int inicio, int ignorar) {\n    bool visitado[g->v];\n    for (int i = 0; i < g->v; i++) {\n        visitado[i] = false;\n    }\n    return dfs(g, inicio, visitado, ignorar);\n}\n\nbool ehCompleto (struct Grafo *g) {\n    for (int u = 0; u < g->v; u++) {\n        if(g->grau[u] != g->v - 1) {\n            return false;\n        }\n    }\n    return true;\n}\n\nbool ehCiclo (struct Grafo *g) {\n    if(g->v < 3) {\n        return false;\n    }\n    for (int u = 0; u < g->v; u++) {\n        if(g->grau[u] != 2) {\n            return false;\n        }\n    }\n    return contarAlcancados(g, 0, -1) == g->v;\n}\n\nbool ehRoda (struct Grafo *g) {\n    int centro = -1;\n    for (int u = 0; u < g->v; u++) {\n        if(g->grau[u] == g->v - 1) {\n            centro = u;\n        }\n    }\n    if(g->v < 4 || centro == -1) {\n        return false;\n    }\n\n    for (int u = 0; u < g->v; u++) {\n        if(u != centro && g->grau[u] != 3) {\n            return false;\n        }\n    }\n    int borda = (centro == 0) ? 1 : 0;\n    return contarAlcancados(g, borda, centro) == g->v - 1;\n}\n\nvoid verificarEuleriano (struct Grafo *g) {\n    int impares = 0;\n    int comArestas = 0;\n    int inicio = -1;\n\n    for (int u = 0; u < g->v; u++) {\n        if(g->grau[u] % 2 != 0) {\n            impares++;\n        }\n        if(g->grau[u] > 0) {\n            comArestas++;\n            inicio = u;\n        }\n    }\n\n    if(g->e == 0 || contarAlcancados(g, inicio, -1) != comArestas) {\n        printf(\"Euleriano: Não\\n\");\n    }\n    else if(impares == 0) {\n        printf(\"Euleriano: Sim (possui ciclo euleriano)\\n\");\n    }\n    else if(impares == 2) {\n        printf(\"Euleriano: Não, mas possui caminho euleriano\\n\");\n    }\n    else {\n        printf(\"Euleriano: Não\\n\");\n    }\n}\n\nbool colorir (struct Grafo *g, int u, int c, int cor[]) {\n    cor[u] = c;\n    for (struct No *p = g->listaAdjacencia[u]; p != NULL; p = p->prox) {\n        int w = p->vertice;\n        if(cor[w] == c || (cor[w] == -1 && !colorir(g, w, 1 - c, cor))) {\n            return false;\n        }\n    }\n    return true;\n}\n\nvoid verificarBipartido (struct Grafo *g) {\n    int cor[g->v];\n    for (int i = 0; i < g->v; i++) {\n        cor[i] = -1;\n    }\n\n    for (int i = 0; i < g->v; i++) {\n        if(cor[i] == -1 && !colorir(g, i, 0, cor)) {\n            printf(\"Bipartido: Não\\n\");\n            return;\n        }\n    }\n\n    printf(\"Bipartido: Sim\\n\");\n    for (int c = 0; c < 2; c++) {\n        printf(\"  %c = { \", c == 0 ? 'X' : 'Y');\n        for (int i = 0; i < g->v; i++) {\n            if(cor[i] == c) {\n                printf(\"%d \", i);\n            }\n        }\n        printf(\"}\\n\");\n    }\n}\n\nvoid moduloClassificacao (struct Grafo *g) {\n    printf(\"\\n===== CLASSIFICAÇÃO =====\\n\");\n    printf(\"Vetor de graus:\\n\");\n    for (int u = 0; u < g->v; u++) {\n        g->grau[u] = 0;\n        for (struct No *p = g->listaAdjacencia[u]; p != NULL; p = p->prox) {\n            g->grau[u]++;\n        }\n        printf(\"Vértice %d: Grau %d\\n\", u, g->grau[u]);\n    }\n\n    printf(\"\\nCompleto:  %s\\n\", ehCompleto(g) ? \"Sim\" : \"Não\");\n    printf(\"Ciclo:     %s\\n\", ehCiclo(g) ? \"Sim\" : \"Não\");\n    printf(\"Roda:      %s\\n\", ehRoda(g) ? \"Sim\" : \"Não\");\n    verificarEuleriano(g);\n    verificarBipartido(g);\n}\n\n//  Operações com matrizes \n\n#define LIMITE 1000000\n\nvoid copiarAdjacencia (struct Grafo *g, int n, int a[n][n]) {\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            a[i][j] = g->adjacencia[i][j];\n        }\n    }\n}\n\nvoid multiplicar (int n, int a[n][n], int b[n][n], int c[n][n]) {\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            c[i][j] = 0;\n            for (int k = 0; k < n; k++) {\n                c[i][j] += a[i][k] * b[k][j];\n            }\n            if(c[i][j] > LIMITE) {\n                c[i][j] = LIMITE;\n            }\n        }\n    }\n}\n\nvoid imprimirQuadrada (int n, int m[n][n]) {\n    printf(\"    \");\n    for (int j = 0; j < n; j++) {\n        printf(\"v%-3d\", j);\n    }\n    printf(\"\\n\");\n    for (int i = 0; i < n; i++) {\n        printf(\"v%-3d\", i);\n        for (int j = 0; j < n; j++) {\n            printf(\"%-4d\", m[i][j]);\n        }\n        printf(\"\\n\");\n    }\n}\n\n// Cliques \n\nvoid imprimirClique (int v, bool membro[], int tamanho) {\n    printf(\"  { \");\n    for (int i = 0; i < v; i++) {\n        if(membro[i]) {\n            printf(\"%d \", i);\n        }\n    }\n    printf(\"} tamanho %d\\n\", tamanho);\n}\n\nvoid detectarTriangulos (int n, int a[n][n], int a2[n][n], int a3[n][n]) {\n    int traco = 0;\n    for (int i = 0; i < n; i++) {\n        traco += a3[i][i];\n    }\n\n    printf(\"\\nTriângulos (K_3):\\n\");\n    for (int i = 0; i < n; i++) {\n        for (int j = i + 1; j < n; j++) {\n            if(a[i][j] == 0 || a2[i][j] == 0) {\n                continue;\n            }\n            for (int k = j + 1; k < n; k++) {\n                if(a[i][k] == 1 && a[j][k] == 1) {\n                    printf(\"  { %d %d %d }\\n\", i, j, k);\n                }\n            }\n        }\n    }\n    printf(\"Total de triângulos: traço(A^3) / 6 = %d / 6 = %d\\n\", traco, traco / 6);\n}\n\nvoid detectarCliquesVizinhanca (struct Grafo *g, int n, int a2[n][n]) {\n    bool encontrados[n][n];\n    int total = 0;\n\n    printf(\"\\nCliques da forma {u} U N(u):\\n\");\n    for (int u = 0; u < n; u++) {\n        bool membro[n];\n        for (int i = 0; i < n; i++) {\n            membro[i] = (g->adjacencia[u][i] == 1);\n        }\n        membro[u] = true;\n\n        bool ehClique = (g->grau[u] > 0);\n        for (struct No *p = g->listaAdjacencia[u]; p != NULL; p = p->prox) {\n            if(a2[u][p->vertice] != g->grau[u] - 1) {\n                ehClique = false;\n            }\n        }\n\n        bool repetido = false;\n        for (int c = 0; c < total; c++) {\n            int i = 0;\n            while (i < n && encontrados[c][i] == membro[i]) {\n                i++;\n            }\n            if(i == n) {\n                repetido = true;\n            }\n        }\n\n        if(ehClique && !repetido) {\n            for (int i = 0; i < n; i++) {\n                encontrados[total][i] = membro[i];\n            }\n            imprimirClique(n, membro, g->grau[u] + 1);\n            total++;\n        }\n    }\n    printf(\"Total de cliques: %d\\n\", total);\n}\n\nbool acharTriangulo (struct Grafo *g, int vertices[], int n, int clique[]) {\n    if(n < 3) {\n        return false;\n    }\n\n    int a[n][n], a2[n][n], a3[n][n];\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            a[i][j] = g->adjacencia[vertices[i]][vertices[j]];\n        }\n    }\n    multiplicar(n, a, a, a2);\n    multiplicar(n, a2, a, a3);\n\n    for (int i = 0; i < n; i++) {\n        if(a3[i][i] == 0) {\n            continue;\n        }\n        for (int j = 0; j < n; j++) {\n            if(a[i][j] == 0 || a2[i][j] == 0) {\n                continue;\n            }\n            for (int k = 0; k < n; k++) {\n                if(a[i][k] == 1 && a[j][k] == 1) {\n                    clique[0] = vertices[i];\n                    clique[1] = vertices[j];\n                    clique[2] = vertices[k];\n                    return true;\n                }\n            }\n        }\n    }\n    return false;\n}\n\nbool buscarClique (struct Grafo *g, int vertices[], int n, int k, int clique[]) {\n    if(k == 3) {\n        return acharTriangulo(g, vertices, n, clique);\n    }\n\n    for (int i = 0; i < n; i++) {\n        int u = vertices[i];\n        int vizinhos[n];\n        int m = 0;\n        for (int j = i + 1; j < n; j++) {\n            if(g->adjacencia[u][vertices[j]] == 1) {\n                vizinhos[m++] = vertices[j];\n            }\n        }\n        if(m >= k - 1 && buscarClique(g, vizinhos, m, k - 1, clique + 1)) {\n            clique[0] = u;\n            return true;\n        }\n    }\n    return false;\n}\n\nbool verificarClique (struct Grafo *g, int k) {\n    int vertices[g->v];\n    int clique[k];\n    for (int i = 0; i < g->v; i++) {\n        vertices[i] = i;\n    }\n\n    if(!buscarClique(g, vertices, g->v, k, clique)) {\n        printf(\"Possui clique de tamanho %d: Não\\n\", k);\n        return false;\n    }\n\n    for (int i = 1; i < k; i++) {\n        for (int j = i; j > 0 && clique[j - 1] > clique[j]; j--) {\n            int aux = clique[j];\n            clique[j] = clique[j - 1];\n            clique[j - 1] = aux;\n        }\n    }\n    printf(\"Possui clique de tamanho %d: Sim { \", k);\n    for (int i = 0; i < k; i++) {\n        printf(\"%d \", clique[i]);\n    }\n    printf(\"}\\n\");\n    return true;\n}\n\nvoid verificarTamanhosClique (struct Grafo *g) {\n    int maior = (g->e > 0) ? 2 : 1;\n\n    printf(\"\\n\");\n    for (int k = 3; verificarClique(g, k); k++) {\n        maior = k;\n    }\n    printf(\"Maior clique: tamanho %d\\n\", maior);\n}\n\nvoid moduloCliques (struct Grafo *g) {\n    int n = g->v;\n    int a[n][n], a2[n][n], a3[n][n];\n\n    printf(\"\\n===== CLIQUES =====\\n\");\n    copiarAdjacencia(g, n, a);\n    multiplicar(n, a, a, a2);\n    multiplicar(n, a2, a, a3);\n\n    printf(\"A^2 (vizinhos em comum):\\n\");\n    imprimirQuadrada(n, a2);\n    printf(\"\\nA^3 (diagonal = 2 x triângulos do vértice):\\n\");\n    imprimirQuadrada(n, a3);\n\n    detectarTriangulos(n, a, a2, a3);\n    detectarCliquesVizinhanca(g, n, a2);\n    verificarTamanhosClique(g);\n}\n\n// Conectividade \n\nvoid moduloConectividade (struct Grafo *g) {\n    int n = g->v;\n    int a[n][n], potencia[n][n], proxima[n][n], soma[n][n];\n\n    printf(\"\\n===== CONECTIVIDADE =====\\n\");\n\n    copiarAdjacencia(g, n, a);\n    copiarAdjacencia(g, n, potencia);\n    copiarAdjacencia(g, n, soma);\n\n    for (int r = 2; r <= n - 1; r++) {\n        multiplicar(n, potencia, a, proxima);\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                potencia[i][j] = proxima[i][j];\n                soma[i][j] += potencia[i][j];\n            }\n        }\n    }\n\n    printf(\"S = A + A^2 + ... + A^%d:\\n\", n - 1);\n    imprimirQuadrada(n, soma);\n\n    bool conexo = true;\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            if(i != j && soma[i][j] == 0) {\n                conexo = false;\n            }\n        }\n    }\n    printf(\"\\nConexo: %s\\n\", conexo ? \"Sim\" : \"Não\");\n}\n\n// Main\n\nint main () {\n    struct Grafo g = {0};\n\n    if(!moduloEntrada(&g)) {\n        liberarGrafo(&g);\n        return EXIT_FAILURE;\n    }\n    moduloTransformacoes(&g);\n    moduloClassificacao(&g);\n    moduloCliques(&g);\n    moduloConectividade(&g);\n\n    liberarGrafo(&g);\n    return 0;\n}\n";
